mapper.select:
select case when count(*) > 0 then true else false end
from category
where parent_id = #{parentId}

select case when count(*) > 0 then true else false end
from category
where name_key = #{nameKey}

select case when count(*) > 0 then true else false end
from category
where slug = #{slug}

select case when count(*) > 0 then true else false end
from category
where name_key = #{nameKey}
    and id != #{excludeId}

select case when count(*) > 0 then true else false end
from category
where slug = #{slug}
    and id != #{categoryId}
